def is_not_prime(numbers):
    for number in numbers:
        if number <= 1:
            return True
        for i in range(2, int(number**0.5) + 1):
            if number % i == 0:
                return True
    return False

def remove_Occ(original_string, character_to_remove):
    if character_to_remove not in original_string:
        return original_string
    else:
        return original_string.replace(character_to_remove, "")

def text_lowercase_underscore(text):
    # Check if the input text is not None and is a string
    if text is not None and isinstance(text, str):
        # Convert the text to lowercase and replace spaces with underscores
        return text.lower().replace(" ", "_")
    else:
        return None  # Return None if the input is None or not a string

def remove_dirty_chars(s):
    if s == '':
        return s
    return ''.join(c for c in s if c.isalnum())

def test_duplicate(arr):
    # Create an empty set to keep track of seen elements
    seen = set()

    # Iterate through each element in the array
    for num in arr:
        # If the element is already in the set, it's a duplicate
        if num in seen:
            return True
        else:
            # Add the element to the set
            seen.add(num)

    # If no duplicates are found, return False
    return False

def is_woodall(n):
    # Check if the number is greater than 1
    if n <= 1:
        return False

    # Check if the number is Woodall
    # A Woodall number is of the form 2^p - 1, where p is a prime number
    # We can iterate through all prime numbers to check if n is of the form 2^p - 1
    for p in range(2, n):
        if pow(2, p) - 1 == n:
            return True
    return False

