def is_octagonal(n):
    # The nth octagonal number is given by the formula: n(3n - 2)
    return n * (3 * n - 2)

def count_Substrings(s: str) -> int:
    if not s:
        return 0
    count = 0
    n = len(s)
    for i in range(n):
        for j in range(i, n):
            count += 1
    return count

def recursive_list_sum(lst):
    if not lst:
        return 0
    else:
        return lst[0] + recursive_list_sum(lst[1:])

def pos_count(numbers):
    count = 0
    for num in numbers:
        if num > 0:
            count += 1
    return count

